import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem124 preserva oferta e afiliado',()=>{for(const [id,titulo,expected,link] of [["pNwNrsWTQMEyOC4qwff1","O Boticário Insensatez Deo Colônia 100ml","O Boticário Insensatez Deo Colônia 100ml","https://www.mercadolivre.com.br/p/MLB19803789?wid=MLB4515776631"],["pO6CZCNo99YwtpIW0UB8","Principia Kit Limpeza E Hidratação Ch-01 + Ol-01 + Gl-02 Todo Tipo De Pele Dia/noite","Principia Kit Limpeza E Hidratação Ch-01 + Ol-01 + Gl-02 Todo Tipo De Pele Dia/noite","https://www.mercadolivre.com.br/p/MLB59624823?pdp_filters=item_id%3AMLB5786186316"],["poypkDuJgaW37aCZlswN","Climatizador Ar Frio Portátil Evaporativo 16 Litros Umidificador Ventisol Clin 16","Climatizador evaporativo Ventisol Clin 16","https://www.mercadolivre.com.br/p/MLB26208174?pdp_filters=item_id%3AMLB5054428609"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
